import pandas as pd
import numpy as np
import re
from collections import defaultdict
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score
import warnings

warnings.filterwarnings("ignore")

# Load data
train_df = pd.read_csv("./input/en_train.csv")
test_df = pd.read_csv("./input/en_test_2.csv")
sample_submission = pd.read_csv("./input/en_sample_submission_2.csv")

# Prepare features: use 'before' column and sentence context
train_df["before"] = train_df["before"].astype(str)
test_df["before"] = test_df["before"].astype(str)

# Drop rows where target 'after' is NaN
train_df = train_df.dropna(subset=["after"])
train_df = train_df.reset_index(drop=True)


# Combine with context: add prev/next tokens (using sentence_id and token_id)
def add_context_features(df):
    df = df.copy()
    df = df.sort_values(["sentence_id", "token_id"]).reset_index(drop=True)

    prev_token = df.groupby("sentence_id")["before"].shift(1).fillna("")
    next_token = df.groupby("sentence_id")["before"].shift(-1).fillna("")

    df["prev_before"] = prev_token
    df["next_before"] = next_token
    return df


train_df = add_context_features(train_df)
test_df = add_context_features(test_df)

# Fill NaN in context for edge cases
train_df["prev_before"] = train_df["prev_before"].fillna("")
train_df["next_before"] = train_df["next_before"].fillna("")
test_df["prev_before"] = test_df["prev_before"].fillna("")
test_df["next_before"] = test_df["next_before"].fillna("")

# Build mapping from before -> after frequency (only for exact matches)
before_to_after = defaultdict(lambda: defaultdict(int))
for i, before in enumerate(train_df["before"]):
    after = train_df["after"].iloc[i]
    before_to_after[before][after] += 1

# Comprehensive normalization functions

# Number normalization
ONES = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
TEENS = [
    "ten",
    "eleven",
    "twelve",
    "thirteen",
    "fourteen",
    "fifteen",
    "sixteen",
    "seventeen",
    "eighteen",
    "nineteen",
]
TENS = [
    "",
    "",
    "twenty",
    "thirty",
    "forty",
    "fifty",
    "sixty",
    "seventy",
    "eighty",
    "ninety",
]
SCALES = ["", "thousand", "million", "billion", "trillion"]


def normalize_number(token):
    try:
        num = int(token.replace(",", ""))
    except:
        return token

    if num == 0:
        return "zero"

    def _handle_chunk(n):
        if n == 0:
            return ""
        result = []
        hundreds = n // 100
        remainder = n % 100

        if hundreds > 0:
            result.append(ONES[hundreds] + " hundred")

        if remainder > 0:
            if remainder < 10:
                result.append(ONES[remainder])
            elif remainder < 20:
                result.append(TEENS[remainder - 10])
            else:
                tens = remainder // 10
                ones = remainder % 10
                if ones > 0:
                    result.append(TENS[tens] + "-" + ONES[ones])
                else:
                    result.append(TENS[tens])

        return " ".join(result)

    words = []
    group_idx = 0
    while num > 0:
        chunk = num % 1000
        if chunk > 0:
            chunk_str = _handle_chunk(chunk)
            # Cap scale index to avoid IndexError for very large numbers
            if group_idx < len(SCALES):
                if group_idx > 0:
                    chunk_str += " " + SCALES[group_idx]
            else:
                # For numbers larger than trillion, just append "billion" as fallback
                chunk_str += " billion"
            words.insert(0, chunk_str)
        num //= 1000
        group_idx += 1

    return " ".join(words)


# Ordinal normalization
def normalize_ordinal(token):
    try:
        num = int(token.replace(",", ""))
        num_str = normalize_number(str(num))
        # Handle special cases
        if num_str.endswith("one"):
            return num_str.replace("one", "first")
        elif num_str.endswith("two"):
            return num_str.replace("two", "second")
        elif num_str.endswith("three"):
            return num_str.replace("three", "third")
        elif num_str.endswith("ty"):
            return num_str.replace("ty", "tieth")
        else:
            return num_str + "th"
    except:
        return token


# Time normalization
def normalize_time(token):
    if re.match(r"^\d{1,2}:\d{2}$", token):
        parts = token.split(":")
        hour = int(parts[0])
        minute = int(parts[1])
        if minute == 0:
            return normalize_number(str(hour)) + " " + "o'clock"
        elif minute < 10:
            return (
                normalize_number(str(hour))
                + " "
                + "oh"
                + " "
                + normalize_number(str(minute))
            )
        else:
            return normalize_number(str(hour)) + " " + normalize_number(str(minute))
    elif re.match(r"^\d{1,2}:\d{2}:\d{2}$", token):
        parts = token.split(":")
        hour = int(parts[0])
        minute = int(parts[1])
        second = int(parts[2])
        result = (
            normalize_number(str(hour))
            + " "
            + normalize_number(str(minute))
            + " "
            + normalize_number(str(second))
        )
        return result
    return token


# Currency normalization
def normalize_currency(token):
    if re.match(r"^\$\d+(\.\d+)?$", token):
        parts = token[1:].split(".")
        dollars = normalize_number(parts[0])
        if len(parts) == 2 and int(parts[1]) > 0:
            cents = normalize_number(parts[1])
            return dollars + " dollars and " + cents + " cents"
        else:
            return dollars + " dollars"
    elif re.match(r"^\d+\.\d+$", token):
        parts = token.split(".")
        whole = normalize_number(parts[0])
        if int(parts[1]) > 0:
            decimal = normalize_number(parts[1])
            return whole + " point " + decimal
        else:
            return whole
    return token


# Date normalization
def normalize_date(token):
    # MM/DD/YYYY
    if re.match(r"^\d{1,2}/\d{1,2}/\d{4}$", token):
        parts = token.split("/")
        month = int(parts[0])
        day = int(parts[1])
        year = parts[2]

        months = [
            "january",
            "february",
            "march",
            "april",
            "may",
            "june",
            "july",
            "august",
            "september",
            "october",
            "november",
            "december",
        ]

        if 1 <= month <= 12:
            month_name = months[month - 1]
            day_str = normalize_ordinal(str(day))
            year_str = normalize_year(year)
            return month_name + " " + day_str + ", " + year_str

    # DD/MM/YYYY
    if re.match(r"^\d{1,2}-\d{1,2}-\d{4}$", token):
        parts = token.split("-")
        day = int(parts[0])
        month = int(parts[1])
        year = parts[2]

        months = [
            "january",
            "february",
            "march",
            "april",
            "may",
            "june",
            "july",
            "august",
            "september",
            "october",
            "november",
            "december",
        ]

        if 1 <= month <= 12:
            month_name = months[month - 1]
            day_str = normalize_ordinal(str(day))
            year_str = normalize_year(year)
            return day_str + " " + month_name + " " + year_str

    return token


def normalize_year(year):
    if year.startswith("00"):
        return normalize_number(year[2:])
    elif year.startswith("0"):
        return "oh" + " " + normalize_number(year[1:])
    else:
        if year[:2] == year[2:]:
            return normalize_number(year[:2]) + " hundred"
        else:
            return normalize_number(year[:2]) + " " + normalize_number(year[2:])


# Measurement normalization
def normalize_measurement(token):
    # Handle measurements like "6ft", "150lb"
    match = re.match(r"^(\d+)([a-zA-Z]+)$", token)
    if match:
        num_str = match.group(1)
        unit = match.group(2).lower()
        num = normalize_number(num_str)

        if unit in ["ft", "foot", "feet"]:
            return num + " feet"
        elif unit in ["lb", "lbs", "pound", "pounds"]:
            return num + " pounds"
        elif unit in ["in", "inch", "inches"]:
            return num + " inches"
        elif unit in ["cm", "centimeter", "centimeters"]:
            return num + " centimeters"
        elif unit in ["km", "kilometer", "kilometers"]:
            return num + " kilometers"
        elif unit in ["m", "meter", "meters"]:
            return num + " meters"

    return token


# General prediction function with comprehensive normalization
def predict_with_rules(before, prev_before, next_before):
    # Rule 1: exact match from training
    if before in before_to_after:
        candidates = before_to_after[before]
        return max(candidates.items(), key=lambda x: x[1])[0]

    # Rule 2: punctuation
    if before in ".,\"!?;:'()-–—":
        return before

    # Rule 3: time patterns
    if re.match(r"^\d{1,2}:\d{2}(:\d{2})?$", before):
        return normalize_time(before)

    # Rule 4: currency patterns
    if re.match(r"^\$\d+(\.\d+)?$", before):
        return normalize_currency(before)

    # Rule 5: date patterns
    if re.match(r"^\d{1,2}/\d{1,2}/\d{4}$", before) or re.match(
        r"^\d{1,2}-\d{1,2}-\d{4}$", before
    ):
        return normalize_date(before)

    # Rule 6: measurement patterns
    if re.match(r"^\d+[a-zA-Z]+$", before):
        return normalize_measurement(before)

    # Rule 7: ordinal patterns (ends with st, nd, rd, th)
    if re.match(r"^\d+(st|nd|rd|th)$", before):
        return normalize_ordinal(before)

    # Rule 8: pure number
    if re.match(r"^\d+$", before):
        return normalize_number(before)

    # Rule 9: number with decimal
    if re.match(r"^\d+\.\d+$", before):
        return normalize_currency(before)

    # Rule 10: default to lowercase
    return before.lower()


